)

export const AccordionItem: FC<AccordionItemProps> = ({
  value,
  variant = 'default',
  class: className,
  children,
  ...props
}) => (
  <div
    data-accordion-item={value}
    data-state="closed"
    class={cn(accordionItemVariants[variant], className)}
