      // Orbit — ring with offset satellite
      return (
        <svg class={svgClass} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
          <circle cx="11" cy="13" r="8" fill="none" stroke="currentColor" stroke-width="3" />
          <circle cx="20" cy="4" r="2.75" />
