      )
    case 3:
      // Pulse — waveform / EKG line
      return (
        <svg
          class={svgClass}
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          stroke-width="2.5"
          stroke-linecap="round"
