        collectionRoutes: publicCollectionRoutes,
        homeRenderer: renderPublicHome,
        homeMarkdown: renderHomeMarkdown,
        notFoundRenderer: renderNotFound,
      });
      mountTypeRoutes(app, getRuntime);
    },
  }),
});

